// Validate input and extract fields from the validation request
const input = $input.first();
const json = input.json || {};

let body = {};
if (json.body && typeof json.body === 'object') { body = json.body; } else if (json.callbackUrl) { body = json; }

const submissionId = body.submissionId;
const standardCode = body.standardCode;
const specCode = body.specCode;
const programLevel = body.programLevel || 'bachelors';
const callbackUrl = body.callbackUrl;
const narrativeText = body.narrativeText || '';
const evidenceText = body.evidenceText || '';
const standardText = body.standardText || '';
const specificationText = body.specificationText || '';
const standardTitle = body.standardTitle || '';
const standardDescription = body.standardDescription || '';
const specTitle = body.specTitle || '';
const specText = body.specText || '';
const evidenceUrls = body.supportingEvidence?.urls || [];
const evidenceFiles = body.supportingEvidence?.documents || [];

if (!callbackUrl) { throw new Error('callbackUrl is required'); }
if (!submissionId) { throw new Error('submissionId is required'); }
if (!standardCode) { throw new Error('standardCode is required'); }
if (!specCode) { throw new Error('specCode is required'); }
if (!narrativeText && !evidenceText) { throw new Error('narrativeText or evidenceText is required'); }

function sanitizeForApi(text) {
  if (!text) return '';
  let clean = text.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
  clean = clean.replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D]/g, '"');
  clean = clean.replace(/[\u2013\u2014]/g, '-');
  clean = clean.replace(/[\u2026]/g, '...');
  clean = clean.replace(/[\uFFFD\uFFFE\uFFFF]/g, '');
  return clean;
}

function stripHtml(html) {
  return html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Strip HTML from narrative to get plain text for AI
const plainNarrative = sanitizeForApi(stripHtml(narrativeText));
const plainEvidence = sanitizeForApi(stripHtml(evidenceText));

console.log('[Validate Input] submissionId:', submissionId);
console.log('[Validate Input] standard:', standardCode, 'spec:', specCode);
console.log('[Validate Input] narrative length:', plainNarrative.length);
console.log('[Validate Input] evidence text length:', plainEvidence.length);
console.log('[Validate Input] evidence URLs:', evidenceUrls.length);
console.log('[Validate Input] evidence files:', evidenceFiles.length);

return [{ json: {
  submissionId,
  standardCode,
  specCode,
  programLevel,
  callbackUrl,
  narrativeText: plainNarrative,
  evidenceText: plainEvidence,
  standardText: sanitizeForApi(standardText),
  specificationText: sanitizeForApi(specificationText),
  standardTitle: sanitizeForApi(standardTitle),
  standardDescription: sanitizeForApi(standardDescription),
  specTitle: sanitizeForApi(specTitle),
  specText: sanitizeForApi(specText),
  evidenceUrls,
  evidenceFiles
} }];

// Fetch HTML content from each evidence URL and extract plain text
const inputData = $input.first().json;
const evidenceUrls = inputData.evidenceUrls || [];

let fetchedContent = '';
const fetchResults = [];

for (const urlInfo of evidenceUrls) {
  const href = urlInfo.href || urlInfo.url;
  if (!href) continue;

  try {
    console.log('[Fetch URLs] Fetching:', href);
    const response = await fetch(href, {
      signal: AbortSignal.timeout(15000),
      headers: { 'User-Agent': 'CSHSE-Validator/1.0' }
    });

    if (!response.ok) {
      console.log('[Fetch URLs] HTTP error:', response.status, 'for', href);
      fetchResults.push({ url: href, status: 'error', error: `HTTP ${response.status}` });
      continue;
    }

    const html = await response.text();

    // Strip HTML to plain text
    const plainText = html
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
      .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
      .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&[a-z]+;/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    // Limit each URL content to 10000 chars
    const truncated = plainText.length > 10000 ? plainText.substring(0, 10000) + '...[truncated]' : plainText;

    fetchedContent += `\n\n--- Content from: ${urlInfo.title || href} ---\n${truncated}`;
    fetchResults.push({ url: href, status: 'success', chars: truncated.length });
    console.log('[Fetch URLs] Success:', href, '- chars:', truncated.length);
  } catch (error) {
    console.log('[Fetch URLs] Error fetching', href, ':', error.message);
    fetchResults.push({ url: href, status: 'error', error: error.message });
  }
}

console.log('[Fetch URLs] Fetched', fetchResults.filter(r => r.status === 'success').length, 'of', evidenceUrls.length, 'URLs');

return [{ json: {
  ...inputData,
  fetchedUrlContent: fetchedContent.trim(),
  fetchResults
} }];

// Build the OpenAI evaluation prompt
const data = $input.first().json;

console.log('[Build Prompt] Standard:', data.standardCode, 'Spec:', data.specCode);
console.log('[Build Prompt] Narrative:', data.narrativeText?.length || 0, 'chars');
console.log('[Build Prompt] Evidence text:', data.evidenceText?.length || 0, 'chars');
console.log('[Build Prompt] Fetched URL content:', data.fetchedUrlContent?.length || 0, 'chars');
console.log('[Build Prompt] Evidence files:', data.evidenceFiles?.length || 0);

// Build the standard reference section
let standardReference = '';
if (data.standardText) {
  standardReference += data.standardText + '\n\n';
}
if (data.specificationText) {
  standardReference += data.specificationText;
} else if (data.specText) {
  standardReference += `Specification ${data.specCode}: ${data.specTitle}\n${data.specText}`;
}

// Build the evidence section
let evidenceSection = '';
if (data.evidenceText) {
  evidenceSection += `=== SUPPORTING EVIDENCE TEXT ===\n${data.evidenceText}\n\n`;
}
if (data.fetchedUrlContent) {
  evidenceSection += `=== CONTENT FROM EVIDENCE URLs ===\n${data.fetchedUrlContent}\n\n`;
}
if (data.evidenceFiles && data.evidenceFiles.length > 0) {
  evidenceSection += `=== EVIDENCE FILES ATTACHED ===\n`;
  for (const file of data.evidenceFiles) {
    evidenceSection += `- ${file.filename || file.originalName} (${file.mimeType || file.type}, ${file.size ? Math.round(file.size / 1024) + 'KB' : 'size unknown'})\n`;
  }
  evidenceSection += '\n';
}

const systemMessage = `You are a CSHSE (Council for Standards in Human Service Education) accreditation evaluator.

Your task is to evaluate whether a self-study narrative and its supporting evidence adequately address and satisfy a specific CSHSE standard and subspecification.

You will be provided with:
1. The CSHSE standard and subspecification text (what must be addressed)
2. The narrative text written by the program (their response)
3. Supporting evidence including text, content from URLs, and list of attached files

EVALUATION CRITERIA:
- Does the narrative directly address the requirements stated in the standard/subspecification?
- Is there sufficient evidence to support the claims made in the narrative?
- Are there specific examples, data, or documentation referenced?
- Are there gaps or missing elements that should be addressed?
- Is the narrative clear, well-organized, and professional?

SCORING GUIDE:
- 80-100: Pass - The narrative and evidence clearly satisfy the standard requirements
- 60-79: Marginal - Some requirements met but notable gaps exist
- 0-59: Fail - Significant requirements are unaddressed or unsupported

A score of 80 or above = "pass", below 80 = "fail".

Provide constructive, specific feedback that helps the program strengthen their self-study.`;

const userMessage = `=== CSHSE STANDARD REQUIREMENT ===

${standardReference || 'Standard ' + data.standardCode + ', Specification ' + data.specCode}

=== PROGRAM NARRATIVE ===

${data.narrativeText || '[No narrative text provided]'}

${evidenceSection ? evidenceSection : '=== NO SUPPORTING EVIDENCE PROVIDED ===\n'}

Evaluate whether the narrative and supporting evidence adequately address and satisfy the CSHSE standard and subspecification requirements above.

Provide your response as JSON with these exact fields:
- status: "pass" or "fail" (pass if score >= 80)
- score: your score from 0-100 as a number
- feedback: A detailed evaluation paragraph (3-5 sentences) explaining your assessment. Reference specific content from the narrative and evidence.
- suggestions: An array of 1-4 specific, actionable suggestions for improvement. Even passing narratives can have suggestions.
- missingElements: An array of 0-4 specific elements that are required by the standard but missing or insufficiently addressed in the narrative. Empty array if all elements are covered.`;

const openaiRequestBody = JSON.stringify({
  model: 'gpt-4o-mini',
  messages: [
    { role: 'system', content: systemMessage },
    { role: 'user', content: userMessage }
  ],
  temperature: 0.3,
  max_tokens: 2000,
  response_format: { type: 'json_object' }
});

console.log('[Build Prompt] Request body length:', openaiRequestBody.length);

return [{ json: { ...data, openaiRequestBody } }];

// Parse the OpenAI API response and extract evaluation result
const apiResponse = $input.first().json;

console.log('[Parse LLM] Received API response');

let aiOutput = null;

try {
  let responseText = '';

  if (apiResponse.choices && apiResponse.choices[0]?.message?.content) {
    responseText = apiResponse.choices[0].message.content;
    console.log('[Parse LLM] Extracted content from choices');
  } else if (apiResponse.message?.content) {
    responseText = apiResponse.message.content;
  } else if (typeof apiResponse === 'string') {
    responseText = apiResponse;
  } else {
    console.log('[Parse LLM] Unexpected response structure');
    responseText = JSON.stringify(apiResponse);
  }

  console.log('[Parse LLM] Response preview:', responseText.substring(0, 300));
  aiOutput = JSON.parse(responseText);
  console.log('[Parse LLM] Successfully parsed JSON');

} catch (parseError) {
  console.log('[Parse LLM] Parse error:', parseError.message);
  try {
    const responseText = apiResponse.choices?.[0]?.message?.content || '';
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      aiOutput = JSON.parse(jsonMatch[0]);
    }
  } catch (e2) {
    console.log('[Parse LLM] Secondary parse failed');
  }
}

if (!aiOutput) {
  aiOutput = {
    status: 'fail',
    score: 0,
    feedback: 'Failed to parse AI evaluation response. Please try again.',
    suggestions: ['Re-run validation'],
    missingElements: []
  };
}

// Normalize
const score = typeof aiOutput.score === 'number' ? aiOutput.score : parseInt(aiOutput.score, 10) || 0;
const result = {
  status: score >= 80 ? 'pass' : 'fail',
  score,
  feedback: String(aiOutput.feedback || 'No feedback provided'),
  suggestions: Array.isArray(aiOutput.suggestions) ? aiOutput.suggestions.map(String) : [],
  missingElements: Array.isArray(aiOutput.missingElements) ? aiOutput.missingElements.map(String) : []
};

console.log('[Parse LLM] Final result:', JSON.stringify(result));

return [{ json: result }];

// Format callback payload for the CSHSE app server
const evaluationResult = $input.first().json;

console.log('[Format Callback] Evaluation result:', JSON.stringify(evaluationResult));

// Get original input data
let inputData = null;
try {
  inputData = $('Validate Input').first().json;
} catch (e1) {
  console.log('[Format Callback] Could not get data from Validate Input:', e1.message);
  try {
    inputData = $('Build Evaluation Prompt').first().json;
  } catch (e2) {
    console.log('[Format Callback] Could not get data from Build Prompt:', e2.message);
  }
}

if (!inputData) {
  inputData = {
    callbackUrl: '',
    submissionId: 'unknown',
    standardCode: 'unknown',
    specCode: 'unknown'
  };
}

console.log('[Format Callback] Callback URL:', inputData.callbackUrl);

// Build callback payload matching the ValidationResponse interface
const callbackPayload = {
  executionId: $execution.id,
  submissionId: inputData.submissionId,
  standardCode: inputData.standardCode,
  specCode: inputData.specCode,
  result: {
    status: evaluationResult.status,
    score: evaluationResult.score,
    feedback: evaluationResult.feedback,
    suggestions: evaluationResult.suggestions,
    missingElements: evaluationResult.missingElements
  }
};

console.log('[Format Callback] Payload created for', inputData.standardCode, inputData.specCode);

return [{ json: {
  callbackUrl: inputData.callbackUrl,
  payload: callbackPayload
} }];

